import{c as s,$ as l,Q as i,j as o,g as e,o as n,n as r,m as d}from"./chunks/framework.Ce_49mA8.js";const y=JSON.parse('{"title":"Инвестиционный портфель","description":"Практическое руководство по учету ценных бумаг, облигаций, криптовалют, долей в бизнесе и выданных займов в ОмниКрафт ЕРП.","frontmatter":{"title":"Инвестиционный портфель","description":"Практическое руководство по учету ценных бумаг, облигаций, криптовалют, долей в бизнесе и выданных займов в ОмниКрафт ЕРП.","datePublished":"2026-10-28","dateModified":"2026-11-15","order":16},"headers":[],"relativePath":"ru/docs/spaces/moy-kapital/investments.md","filePath":"ru/docs/spaces/moy-kapital/investments.md","lastUpdated":1794700800000}'),m={name:"ru/docs/spaces/moy-kapital/investments.md"},g={id:"инвестиционныи-портфель-сохранение-и-рост-капитала",tabindex:"-1"};function c(p,t,h,u,f,b){const a=l("DocIcon");return i(),o("div",null,[e("h1",g,[n(a,{name:"capital"}),t[0]||(t[0]=r(" Инвестиционный портфель: Сохранение и рост капитала ",-1)),t[1]||(t[1]=e("a",{class:"header-anchor",href:"#инвестиционныи-портфель-сохранение-и-рост-капитала","aria-label":'Permalink to "Инвестиционный портфель: Сохранение и рост капитала"'},"​",-1))]),t[2]||(t[2]=d('<p>Вкладка <strong>«Инвестиционный портфель»</strong> предназначена для активов, главной целью которых выступает сохранение и долгосрочное приумножение личного капитала мастера. В отличие от операционной кассы цеха и текущих расчетных карт, здесь аккумулируются инструменты с инвестиционным горизонтом: акции и облигации на брокерских счетах, биржевые фонды, цифровые расчетные резервы, доли в партнерских проектах и выданные процентные займы.</p><p>Грамотно выстроенный инвестиционный контур формирует надежную финансовую подушку безопасности. Доходы от внешних активов защищают ремесленное дело во время сезонных спадов спроса, при задержках поставок сырья или модернизации парка оборудования.</p><hr><h2 id="трехуровневая-архитектура-портфеля" tabindex="-1">Трехуровневая архитектура портфеля <a class="header-anchor" href="#трехуровневая-архитектура-портфеля" aria-label="Permalink to &quot;Трехуровневая архитектура портфеля&quot;">​</a></h2><p>Для строгого порядка в структуре инвестиций реализована трехуровневая модель распределения активов:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Класс активов] ➔ [Площадка / Брокер] ➔ [Финансовые инструменты]</span></span></code></pre></div><ol><li><strong>Класс активов (Категория групп):</strong> верхнеуровневый контур распределения рисков (<em>«Акции»</em>, <em>«Облигации и фонды»</em>, <em>«Криптовалюта»</em>, <em>«Прямые инвестиции и доли»</em>, <em>«Выданные займы»</em>).</li><li><strong>Площадка / Брокер (Группа активов):</strong> конкретное место размещения капитала (<em>«Основной брокер»</em>, <em>«Аппаратный криптокошелек»</em>, <em>«Венчурный проект мастерской»</em>).</li><li><strong>Финансовые инструменты (Позиции):</strong> отдельные активы с зафиксированной суммой вложений, текущей рыночной оценкой и валютой (<em>«Акции Сбера»</em>, <em>«ОФЗ 26238»</em>, <em>«Биткоин»</em>, <em>«Доля 25% в мастерской выкроек»</em>).</li></ol><hr><h2 id="сводные-индикаторы-и-полоса-распределения-капитала" tabindex="-1">Сводные индикаторы и полоса распределения капитала <a class="header-anchor" href="#сводные-индикаторы-и-полоса-распределения-капитала" aria-label="Permalink to &quot;Сводные индикаторы и полоса распределения капитала&quot;">​</a></h2><p>В верхней части экрана размещена информационная панель ключевых показателей портфеля мастера:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Иконка графика] ОБЪЕМ ПОРТФЕЛЯ: 3 850 000,00 ₽  |  Вложено: 3 200 000,00 ₽  |  Результат: +650 000,00 ₽ (+20.3%)</span></span></code></pre></div><ul><li><strong>«Объем портфеля»:</strong> совокупная рыночная стоимость всех инвестиционных инструментов, приведенная к базовой валюте учета;</li><li><strong>«Вложено капитала»:</strong> сумма фактически направленных личных средств на покупку активов;</li><li><strong>«Финансовый результат»:</strong> накопленная чистая прибыль или убыток в денежном выражении и в процентах годовых (положительный результат подсвечивается зеленым цветом, просадка — красным).</li></ul><h3 id="полоса-распределения-капитала" tabindex="-1">Полоса распределения капитала <a class="header-anchor" href="#полоса-распределения-капитала" aria-label="Permalink to &quot;Полоса распределения капитала&quot;">​</a></h3><p>Прямо под числовыми индикаторами расположена мультисегментная цветная шкала долей портфеля:</p><ul><li>Каждый сегмент окрашен в цвет своего класса активов;</li><li>Длина сегмента строго пропорциональна процентному весу класса в общем инвестиционном капитале;</li><li>При наведении курсора на сегмент или элемент легенды программа отображает точную сумму и процентную долю класса в портфеле.</li></ul><div class="tip custom-block"><p class="custom-block-title">Балансировка рисков портфеля</p><p>Если доля высокорискованных инструментов превышает запланированный порог, цветная шкала наглядно продемонстрирует перекос. Это позволяет вовремя перенаправить свободную прибыль мастерской в защитные облигации или депозиты.</p></div><hr><h2 id="математическая-модель-расчета-доходности" tabindex="-1">Математическая модель расчета доходности <a class="header-anchor" href="#математическая-модель-расчета-доходности" aria-label="Permalink to &quot;Математическая модель расчета доходности&quot;">​</a></h2><p>Для каждого инвестиционного инструмента программа в реальном времени вычисляет абсолютный финансовый результат и относительную отдачу на капитал:</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Инвестиционная доходность</span><div class="formula-heading">Расчет финансового результата и отдачи на капитал</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Финансовый результат (₽)</span><span class="math-op">=</span><span class="math-var">Текущая рыночная стоимость</span><span class="math-op">−</span><span class="math-var">Вложенный капитал</span></div></div><div class="formula-card-bottom"><p>Процентная доходность вычисляется как отношение полученного финансового результата к сумме первоначальных инвестиций, умноженное на 100%. Система учитывает курсовые разницы для валютных активов, пересчитывая показатели по единому базовому курсу.</p></div></div><p>Кроме того, программа рассчитывает многоуровневые веса:</p><ul><li><strong>Доля класса в портфеле:</strong> вес направления в общей сумме инвестиций;</li><li><strong>Доля площадки:</strong> удельный вес брокера или депозитария;</li><li><strong>Доля инструмента:</strong> вес конкретной бумаги в портфеле и ее доля внутри своего брокерского счета.</li></ul><hr><h2 id="добавление-и-справочник-параметров-инвестиции" tabindex="-1">Добавление и справочник параметров инвестиций <a class="header-anchor" href="#добавление-и-справочник-параметров-инвестиции" aria-label="Permalink to &quot;Добавление и справочник параметров инвестиций&quot;">​</a></h2><p>При нажатии кнопки <strong>«Добавить»</strong> открывается окно с выбором сценария:</p><ol><li><strong>Режим «Одиночный актив»:</strong> быстрое заведение независимого договора займа, отдельного слитка драгоценного металла или прямой доли в бизнесе.</li><li><strong>Режим «Группа / Брокер / Площадка»:</strong> пакетное формирование брокерского портфеля с добавлением нескольких активов через кнопку <strong>«Добавить актив в группу»</strong>.</li></ol><table tabindex="0"><thead><tr><th style="text-align:left;">Поле ввода</th><th style="text-align:left;">Назначение и формат</th><th style="text-align:left;">Пример значения</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>«Наименование актива»</strong></td><td style="text-align:left;">Понятное имя бумаги, фонда или доли</td><td style="text-align:left;"><em>Акции Сбера</em>, <em>ОФЗ 26238</em>, <em>Доля 25% в мастерской</em></td></tr><tr><td style="text-align:left;"><strong>«Площадка (Брокер)»</strong></td><td style="text-align:left;">Место хранения актива или брокерская компания</td><td style="text-align:left;"><em>Т-Инвестиции</em>, <em>Финам</em>, <em>Холодный сейф</em></td></tr><tr><td style="text-align:left;"><strong>«Класс активов»</strong></td><td style="text-align:left;">Категория риска для расчета распределения</td><td style="text-align:left;"><em>Акции</em>, <em>Облигации и фонды</em>, <em>Прямые инвестиции</em></td></tr><tr><td style="text-align:left;"><strong>«Валюта и курс»</strong></td><td style="text-align:left;">Валюта инструмента и множитель пересчета к базовой единице</td><td style="text-align:left;"><em>рубли (₽)</em>, <em>доллары ($)</em>, <em>евро (€)</em>, <em>USDT</em></td></tr><tr><td style="text-align:left;"><strong>«Вложено капитала»</strong></td><td style="text-align:left;">Фактические затраты на приобретение актива</td><td style="text-align:left;"><em>250 000,00 ₽</em></td></tr><tr><td style="text-align:left;"><strong>«Текущая стоимость»</strong></td><td style="text-align:left;">Актуальная рыночная оценка позиции на день ревизии</td><td style="text-align:left;"><em>310 000,00 ₽</em></td></tr><tr><td style="text-align:left;"><strong>«Ссылка на карточку»</strong></td><td style="text-align:left;">Прямой веб-адрес терминала биржи или карточки эмитента</td><td style="text-align:left;"><code>https://www.moex.com/</code></td></tr><tr><td style="text-align:left;"><strong>«Заметки и стратегия»</strong></td><td style="text-align:left;">Горизонт удержания, даты выплат купонов или дивидендов</td><td style="text-align:left;"><em>Выплата купонного дохода дважды в год</em></td></tr></tbody></table><hr><h2 id="фиксация-продажи-и-закрытие-позиции" tabindex="-1">Фиксация продажи и закрытие позиций <a class="header-anchor" href="#фиксация-продажи-и-закрытие-позиции" aria-label="Permalink to &quot;Фиксация продажи и закрытие позиций&quot;">​</a></h2><p>Когда инвестиционная цель достигнута, наступил срок погашения облигации или партнер вернул тело займа с процентами, позиция закрывается через диалоговое окно фиксации сделки:</p><ol><li>Нажмите кнопку с иконкой закрытия в строке или карточке актива;</li><li>В открывшемся окне укажите <strong>фактическую цену продажи</strong> и дату завершения операции;</li><li>Программа мгновенно рассчитает зафиксированный чистый финансовый результат (прибыль или убыток) в деньгах и процентах;</li><li><strong>Сквозной перевод средств:</strong> система предложит зачислить полученную сумму (тело инвестиции плюс прибыль) на один из активных счетов во вкладке <strong>«Счета и кошельки»</strong>;</li><li>Закрытая позиция автоматически отправляется в архив, исключая задвоение текущих балансов и сохраняя чистую историю доходности.</li></ol><div class="info custom-block"><p class="custom-block-title">Сквозной денежный перевод</p><p>Автоматический перевод выручки от закрытия инвестиции на расчетный счет устраняет разрывы в цепочке капитала. Деньги сразу становятся доступными в ликвидном контуре для новых вложений или финансирования мастерской.</p></div><hr><h2 id="управление-площадками-и-режимы-отображения" tabindex="-1">Управление площадками и режимы отображения <a class="header-anchor" href="#управление-площадками-и-режимы-отображения" aria-label="Permalink to &quot;Управление площадками и режимы отображения&quot;">​</a></h2><p>Для оперативной работы со списком активов карточки брокеров оснащены удобными элементами управления:</p><ul><li><strong>Кнопка «+»:</strong> моментальное добавление нового инструмента на выбранную площадку;</li><li><strong>Стрелки «↑» и «↓»:</strong> ручная перестановка карточек брокеров и позиций для расстановки приоритетов;</li><li><strong>Кнопка с карандашом:</strong> комплексное управление площадкой — пакетное переименование с каскадным обновлением всех связанных инструментов, изменение класса активов и ревизия состава;</li><li><strong>Переключатель видов («Плитка» / «Полосы»):</strong> переход от просторной галереи колонок к плотному вертикальному списку в формате аккордеона с глобальной кнопкой <strong>«↕»</strong> для одновременного сворачивания и раскрытия всех групп.</li></ul><div class="warning custom-block"><p class="custom-block-title">Сохранение истории доходности</p><p>При продаже или выходе из актива никогда не удаляйте запись физически. Используйте штатный механизм закрытия сделки либо отправку в архив. Это сохраняет корректность ретроспективной финансовой аналитики за прошлые годы.</p></div><hr><h2 id="разбор-внештатных-ситуации-troubleshooting" tabindex="-1">Разбор внештатных ситуаций (Troubleshooting) <a class="header-anchor" href="#разбор-внештатных-ситуации-troubleshooting" aria-label="Permalink to &quot;Разбор внештатных ситуаций (Troubleshooting)&quot;">​</a></h2><div class="faq-grid"><details class="faq-item"><summary class="faq-summary">Что делать, если процент доходности актива рассчитывается с искажением?</summary><div class="faq-content"><p>Проверьте поле «Вложено капитала»: там должна быть указана фактическая себестоимость покупки без учета реинвестированных дивидендов. При использовании валютных инструментов проверьте курс в диалоге «Курсы валют».</p></div></details><details class="faq-item"><summary class="faq-summary">Почему сумма от продажи актива не зачислилась на банковский счет?</summary><div class="faq-content"><p>При закрытии сделки необходимо подтвердить диалог сквозного зачисления и выбрать целевой счет из списка. Если перевод не был подтвержден, внесите поступление на счет вручную во вкладке «Счета и деньги».</p></div></details><details class="faq-item"><summary class="faq-summary">Как скрыть неиспользуемую брокерскую площадку без потери истории сделок?</summary><div class="faq-content"><p>Кликните по иконке карандаша на заголовке брокера и выберите «Архивировать площадку». Карточка скроется из активного окна, а закрытые сделки сохранятся в исторической аналитике портфеля.</p></div></details></div>',40))])}const x=s(m,[["render",c]]);export{y as __pageData,x as default};
